from pathlib import Path
import ast

TARGET=Path("qseries_v2/oracle_execution/solana_atomic_executor/mry_008_execution_readiness.py")
TEST=Path("test_mry_008_execution_readiness.py")

MODULE='from __future__ import annotations\nimport copy\n\nCANARY_LAMPORTS=10_000_000\n\ndef _programs(rt,token):\n    row=rt.q25.q23.worker().warm(token)\n    return str(row["program"]),str(rt.q87.c.TOKEN)\n\ndef prepare_forward(rt,pair):\n    token=str(pair.token)\n    pool=str(pair.pump_pool)\n    token_program,wsol_program=_programs(rt,token)\n\n    ixs,_=rt.q87.las.q59.native_pump_buy_ixs(\n        rt.USER,\n        pool,\n        CANARY_LAMPORTS,\n    )\n\n    pump_index=rt.pump_ix_position(ixs)\n\n    pump_template={\n        "pump_pool":pool,\n        "instructions":[copy.deepcopy(x) for x in ixs],\n        "pump_index":int(pump_index),\n        "template_quote_lamports":CANARY_LAMPORTS,\n    }\n\n    tx=str(pair.token_x)\n    ty=str(pair.token_y)\n    programs={\n        token:token_program,\n        rt.q87.c.WSOL:wsol_program,\n    }\n\n    tx_prog=programs.get(tx)\n    ty_prog=programs.get(ty)\n\n    if not tx_prog or not ty_prog:\n        raise RuntimeError("TOKEN_PROGRAM_NOT_READY")\n\n    user=rt.USER\n    mpool=str(pair.meteora_pool)\n\n    ux=rt.q87.c.ata(user,tx,tx_prog)\n    uy=rt.q87.c.ata(user,ty,ty_prog)\n\n    rx=rt.q87.c.pda(\n        [rt.q87.c.b58d(mpool),rt.q87.c.b58d(tx)],\n        rt.q87.c.DLMM,\n    )\n    ry=rt.q87.c.pda(\n        [rt.q87.c.b58d(mpool),rt.q87.c.b58d(ty)],\n        rt.q87.c.DLMM,\n    )\n    oracle=rt.q87.c.pda(\n        [b"oracle",rt.q87.c.b58d(mpool)],\n        rt.q87.c.DLMM,\n    )\n    bitmap=rt.q87.c.pda(\n        [b"bitmap",rt.q87.c.b58d(mpool)],\n        rt.q87.c.DLMM,\n    )\n    event=rt.q87.c.pda(\n        [b"__event_authority"],\n        rt.q87.c.DLMM,\n    )\n\n    bitmap_account=rt.q87.c.rpc(\n        "getAccountInfo",\n        [bitmap,{"encoding":"base64","commitment":"processed"}],\n    )\n\n    bitmap_key=(\n        bitmap\n        if isinstance(bitmap_account,dict)\n        and bitmap_account.get("value")\n        else rt.q87.c.DLMM\n    )\n\n    if tx==rt.q87.c.WSOL:\n        source=uy\n        dest=ux\n        swap_for_y=False\n    elif ty==rt.q87.c.WSOL:\n        source=ux\n        dest=uy\n        swap_for_y=True\n    else:\n        raise RuntimeError("DLMM_NOT_WSOL")\n\n    fixed=[\n        (mpool,False,True),\n        (bitmap_key,False,True),\n        (rx,False,True),\n        (ry,False,True),\n        (source,False,True),\n        (dest,False,True),\n        (tx,False,False),\n        (ty,False,False),\n        (oracle,False,True),\n        (rt.q87.c.DLMM,False,True),\n        (user,True,False),\n        (tx_prog,False,False),\n        (ty_prog,False,False),\n        (event,False,False),\n        (rt.q87.c.DLMM,False,False),\n    ]\n\n    meteora_template={\n        "pool":mpool,\n        "token_x":tx,\n        "token_y":ty,\n        "swap_for_y":bool(swap_for_y),\n        "arrays":[\n            (int(a[0]),str(a[1]))\n            for a in list(pair.arrays)\n        ],\n        "fixed_accounts":fixed,\n    }\n\n    rt.q18.worker().warm(pool)\n\n    return (\n        pump_template,\n        meteora_template,\n        token_program,\n    )\n\ndef install_forward(rt,pair):\n    token=str(pair.token)\n    pump,meteora,program=prepare_forward(rt,pair)\n\n    rt.TEMPLATES[token]=pump\n    rt.METEORA_TEMPLATES[token]=meteora\n\n    print(\n        "[MRIYA_EXECUTION_READY] "\n        "token=%s forward=TRUE "\n        "reverse=UNCHANGED quote_lamports=%d"\n        %(token[:10],CANARY_LAMPORTS),\n        flush=True,\n    )\n\n    return {\n        "token":token,\n        "program":program,\n        "forward":True,\n    }\n'
TEST_SOURCE='import unittest\nfrom qseries_v2.oracle_execution.solana_atomic_executor import mry_008_execution_readiness as m\n\nclass T(unittest.TestCase):\n    def test_exact_canary(self):\n        self.assertEqual(m.CANARY_LAMPORTS,10_000_000)\n\n    def test_api(self):\n        self.assertTrue(callable(m.prepare_forward))\n        self.assertTrue(callable(m.install_forward))\n\nif __name__=="__main__":\n    unittest.main(verbosity=2)\n'

ast.parse(MODULE)
ast.parse(TEST_SOURCE)
TARGET.parent.mkdir(parents=True,exist_ok=True)
TARGET.write_text(MODULE,encoding="utf-8")
TEST.write_text(TEST_SOURCE,encoding="utf-8")

print("[PASS] MRY-008 installed")
print("[PASS] module:",TARGET)
print("[PASS] test:",TEST)
